mapper.select:
SELECT id, provider_code, provider_name, preset_dict_id, base_url, tenant_id, owner_user_id, status, (CASE WHEN api_key_value IS NOT NULL AND TRIM(api_key_value) != '' THEN TRUE ELSE FALSE END) AS credential_configured, lock_version, update_time FROM blade_ai_provider_config WHERE is_deleted = 0
AND tenant_id = #{param.tenantId}
AND owner_user_id = #{param.ownerUserId}
AND provider_code LIKE CONCAT('%', #{param.providerCode}, '%')
AND provider_name LIKE CONCAT('%', #{param.providerName}, '%')
AND status = #{param.status}
ORDER BY update_time DESC, id DESC
